# Se ejecuta cada celda de codigo y se capturan sus salidas reales.
cells=[];ns={'ROOT':ROOT};execution=0

def md(source):cells.append({'cell_type':'markdown','metadata':{},'source':source.splitlines(keepends=True)})
def code(source):
    global execution
    execution+=1;stream=io.StringIO()
    with contextlib.redirect_stdout(stream):exec(compile(source,f'celda_{execution}','exec'),ns)
    output=stream.getvalue()
    cells.append({'cell_type':'code','metadata':{},'source':source.splitlines(keepends=True),'execution_count':execution,'outputs':[{'output_type':'stream','name':'stdout','text':output.splitlines(keepends=True)}] if output else []})
md('# Nueva York en movimiento\n## Taxis amarillos y clima, 2024\nEDA reproducible de dos fuentes independientes: NYC TLC y NOAA. El dataset final supera los minimos del master. Todas las salidas de codigo incluidas se han ejecutado sobre los archivos entregados.')
code("from pathlib import Path\nimport json\nimport pandas as pd\nimport numpy as np\nROOT = Path.cwd()\nif not (ROOT / 'data').exists(): ROOT = ROOT.parent\ndf = pd.read_parquet(ROOT / 'data/processed/taxi_clima_final.parquet')\nprint('Dimensiones:', df.shape)\nprint('Fechas UTC:', df.fecha_utc.min(), df.fecha_utc.max())\nprint(df[['fecha_utc','duracion_min','distancia_km','fare_amount','lluvia']].head().to_string(index=False))")
md('## 1. Fuentes y diseno muestral\nSe toman 50.000 filas sin limpiar por mes, sin reemplazo, usando semilla 202400+mes. Los valores fuente se conservan en el extracto bruto. Las dos columnas anadidas permiten localizar la fila de origen. El peso es N del mes / 50.000. Data.gov es el catalogo, TLC y NOAA son los productores independientes.')
code("manifest = json.loads((ROOT/'data/raw/manifiesto_tlc.json').read_text())\nprint(pd.DataFrame(manifest)[['mes','filas_originales','filas_extraidas','semilla']].to_string(index=False))\nprint('Total fuente:', sum(x['filas_originales'] for x in manifest))")
md('## 2. Limpieza y controles\nLas reglas estan implementadas en src/01_preparar.py. No se imputan pasajeros o precipitacion ausentes. Las horas ambiguas del cambio de horario se excluyen. Se conservan unicamente dias UTC completos. La union se valida como muchos-a-uno, sin multiplicar viajes.')
code("quality = json.loads((ROOT/'reports/validacion_final.json').read_text(encoding='utf-8'))\nprint(json.dumps(quality,ensure_ascii=False,indent=2))\nassert len(df)>=50000 and len(df.columns)>=20\nassert not df.duplicated(['mes_archivo','fila_origen']).any()\nassert df.estacion_meteo.notna().all()\nprint(pd.read_csv(ROOT/'reports/calidad_datos.csv').query('ausentes > 0').to_string(index=False))")
md('## 3. EDA ponderado\nLos meses tienen el mismo tamano muestral, pero distinto numero de registros fuente. Por eso las medias, porcentajes, totales y cuantiles del informe utilizan pesos. La proporcion de propina agregada es una razon de sumas, no la media de porcentajes por viaje.')
code("w = df.peso_muestral\nfor col in ['duracion_min','distancia_km','fare_amount','total_amount']:\n    print(col, 'media ponderada =', round(np.average(df[col],weights=w),3))\ncard = df[df.payment_type.eq(1)]\nprint('Propina / tarifa tarjeta (%) =',100*(card.tip_amount*card.peso_muestral).sum()/(card.fare_amount*card.peso_muestral).sum())\nprint('Volumen valido estimado =',w.sum())")
md('## 4. Tabla diaria e independencia\nCada fila de esta tabla es un dia UTC completo. Para estudiar el clima, 576.606 viajes no equivalen a 576.606 observaciones meteorologicas independientes. Hay 365 dias, con 138 dias de lluvia indicada y 227 sin indicador. El cero del indicador NOAA puede significar no o no reportado.')
code("daily = pd.read_csv(ROOT/'data/processed/resumen_diario.csv')\nprint(daily[['fecha_utc','viajes_estimados','duracion_media','lluvia_indicada']].head().to_string(index=False))\nprint('Dias:',len(daily))\nprint(daily.lluvia_indicada.value_counts().to_string())")
md('## 5. Modelo ajustado de actividad\nSe ajusta log(volumen diario estimado) por lluvia, temperatura, nieve, mes y dia semanal UTC. Los errores HAC con siete retardos contemplan dependencia temporal semanal y heterocedasticidad. Es asociacion observacional, no efecto causal.')
code("import statsmodels.formula.api as smf\nmodel = smf.ols('np.log(viajes_estimados) ~ lluvia_num + temperatura_c + nieve_num + C(mes) + C(dia_semana)',data=daily).fit(cov_type='HAC',cov_kwds={'maxlags':7})\nprint(model.summary().as_text())\nprint('Cambio ajustado por lluvia (%):',100*np.expm1(model.params['lluvia_num']))")
md('## 6. Tres preguntas y correccion de Holm\nSe ajustan tres modelos diarios: volumen, duracion (tambien ajustada por distancia media) y razon de propina sobre tarifa en tarjeta. Se corrigen los tres p-valores de lluvia con Holm. Los intervalos del informe son puntuales del 95%, no simultaneos corregidos.')
code("results = pd.read_csv(ROOT/'reports/resultados_estadisticos.csv')\nprint(results[['modelo','efecto','ic95_inferior','ic95_superior','p_holm','n_dias']].to_string(index=False))\nassert (results.n_dias==365).all()\nprint('Ninguna prueba tiene p Holm < 0.05:', (results.p_holm>=.05).all())")
md('## 7. Visualizaciones e interpretacion\nLas siete figuras estan en reports/figuras y en la memoria PDF. Los graficos horarios comparan viajes medios por dia, no totales de grupos con distinto numero de dias. Los histogramas recortan solo el eje mostrado. El dashboard muestra comparaciones descriptivas; no sustituye los modelos ajustados.\n\n![Actividad mensual](../reports/figuras/01_actividad_mensual.png)\n![Perfil horario](../reports/figuras/04_perfil_horario.png)\n![Modelos](../reports/figuras/06_modelos.png)')
md('## 8. Sensibilidad, conclusiones y limites\nAl reducir el maximo de duracion a 120 minutos, la estimacion de volumen asociada con lluvia pasa de 2,58% a 2,57%. Las asociaciones no alcanzan significacion al 5%; no se demuestra ausencia de efecto. Una estacion y un indicador diario limitan la medicion. No se incluyen festivos o disponibilidad de taxis y el volumen es una estimacion muestral.\n\nPara reconstruir todos los resultados: ejecutar src/01_preparar.py y src/02_analizar.py. Para reconstruir la muestra desde las fuentes completas: src/00_descargar.py. La memoria detalla la metodologia y las referencias.')
md('## 9. El razonamiento detrás de las fórmulas\nLa guía [Guia_razonamiento.md](../reports/Guia_razonamiento.md) desarrolla catorce decisiones: pregunta, qué se hizo, por qué y límites. En Excel se explican también junto a los cálculos y en Razonamiento. El siguiente ejemplo es didáctico; sus números no proceden del dataset.')
code("duraciones = np.array([10.,20.])\npesos_ejemplo = np.array([60.,80.])\nprint('Media simple:',duraciones.mean())\nprint('Media ponderada:',np.average(duraciones,weights=pesos_ejemplo))\nprint('La segunda pondera la distinta cantidad de viajes representados.')")
md('## 10. Diagnóstico: no basta con mirar p-valores\nSe examinan autocorrelación, heterocedasticidad e influencia. HAC corrige la covarianza bajo sus supuestos, pero no elimina la estructura temporal de los residuos. El modelo dinámico cambia la pregunta al condicionar a actividad previa. Los diagnósticos son exploratorios.')
code("diag = pd.read_csv(ROOT/'reports/diagnosticos_modelos.csv')\nprint(diag.to_string(index=False))")
md('## 11. Sensibilidad: mostrar todas las especificaciones\nSe informan ocho variantes, incluidos festivos, días influyentes, tendencia flexible y actividad del día previo. El intervalo nominal excluye cero al retirar cinco días: no se escoge esa variante como confirmación. Los tres modelos principales mantienen Holm; las sensibilidades son exploratorias.\n\n![Diagnósticos](../reports/figuras/10_diagnosticos.png)\n![Sensibilidad](../reports/figuras/11_sensibilidad.png)')
code("sens = pd.read_csv(ROOT/'reports/sensibilidad_ampliada.csv')\nprint(sens[['especificacion','efecto_pct','ic95_inferior','ic95_superior','p_exploratorio','n_dias']].to_string(index=False))")

